<template><div class="request-table"><table><colgroup><col class="idcol"><col class="datecol"><col class="clientcol"><col class="devicecol"><col class="statuscol"><col class="actioncol"></colgroup><thead><tr><th>ID Demande</th><th>Date　↕</th><th>Client　↕</th><th>Appareil & panne　↕</th><th>Statut　↕</th><th>Actions</th></tr></thead><tbody><tr v-for="item in demandes" :key="item.id"><td class="id">{{item.id}}</td><td class="date">▣　<b>{{item.date}}</b><small>{{item.time}}</small></td><td class="client"><b>♟　 {{item.client}}</b><small>⌕　 {{item.phone}}</small><small>●　 {{item.zone}}</small></td><td class="device"><i>{{item.icon}}</i><span><b>{{item.device}}</b><small>{{item.issue}}</small></span></td><td><mark :class="item.status.toLowerCase().replace(' ','-')">{{statusIcon(item.status)}}　{{item.status}}</mark></td><td class="actions"><button @click="$emit('detail',item)">◉　 Voir plus</button><button @click="$emit('delete',item)">♜　 Supprimer</button></td></tr><tr v-if="!demandes.length"><td colspan="6" class="empty">Aucune demande ne correspond à la recherche.</td></tr></tbody></table></div></template>
<script setup>defineProps({demandes:{type:Array,required:true}});defineEmits(['detail','delete']);const statusIcon=s=>s==='En attente'?'◔':'✓'</script>
<style scoped>.request-table{overflow:auto;margin:2px 10px 0;border:1px solid #ddebfb;border-radius:9px}table{border-collapse:collapse;width:100%;min-width:1080px;background:#fff;table-layout:fixed}.idcol{width:11.5%}.datecol{width:10.7%}.clientcol{width:17.7%}.devicecol{width:21.1%}.statuscol{width:14.6%}.actioncol{width:24.4%}th{height:59px;text-align:left;text-transform:uppercase;color:#1850a3;background:#e8f6f2;font-size:12px;padding:19px}td{height:116px;padding:17px 19px;border-bottom:1px solid #dfeefa;color:#4c71ad;font-size:14px}tbody tr:nth-child(even){background:#f0faf8}tbody tr:nth-child(odd){background:#fff}tr:last-child td{border:0}.id{font-size:16px;font-weight:800;color:#174b50;white-space:nowrap}.date{color:#5176b7}.date b{color:#174b50}.date small,.client small,.device small{display:block;margin:8px 0 0 29px;color:#6686bd}.client b{display:block;color:#174b50;font-size:14px}.device{display:flex;align-items:center;gap:16px;color:#174b50}.device i{font-size:36px;font-style:normal}.device b{display:block;font-size:14px}.device small{margin-left:0}.actions{white-space:nowrap}.actions button{padding:12px 16px;border-radius:8px;border:1px solid #77aeff;background:#fff;color:#087f70;font-size:12px}.actions button+button{margin-left:10px;border-color:#ff879a;color:#ff304d}mark{display:inline-block;padding:10px 15px;border-radius:22px;background:#fff1d8;color:#e88a00;font-size:12px}.acceptée,.terminée{background:#ddf8ed;color:#00a879}.empty{text-align:center;color:#6681b2}</style>
